const clamp=x=>Math.max(0,Math.min(1,x));export const smooth=x=>{x=clamp(x);return x*x*(3-2*x)};
const hash=(n,seed)=>{const v=Math.sin(n*127.1+seed*311.7)*43758.5453;return v-Math.floor(v)};
export function battleState(age,f){const glide=smooth(age/Math.max(.1,f.battleGlide)),growth=smooth((age-f.battleBlastStart)/Math.max(.1,f.battleBlastGrow));const elapsed=Math.max(0,age-f.battleBlastStart),decay=smooth((elapsed-f.battleBlastGrow-1)/Math.max(.1,f.battleBlastDecay??7));return {fire:smooth(age/Math.max(.1,f.battleFireBuild??3))*(1-smooth((age-f.battleBlastStart)/4)),blastOpacity:age<f.battleBlastStart?0:smooth(elapsed/.35)*(1-decay),blastRise:elapsed*(f.battleBlastRise??9),glide,incoming:(f.battleDirection==='right'?1:-1)*960*(1-glide),outgoing:(f.battleDirection==='right'?-1:1)*960*glide,growth,blastScale:f.battleBlastSize*(.2+growth*.8),fog:smooth((age-f.battleFogStart)/Math.max(.1,f.battleFogBuild)),smoke:smooth((age-f.battleSmokeStart)/Math.max(.1,f.battleSmokeGrow))}}
export function shotEvents(duration,seed=17,rate=1,count=4,mode='staggered'){const events=[];let time=.8,index=0;while(time<duration&&index<500){const group=mode==='single'?1:hash(index+40,seed)>.57?2:1,first=Math.floor(hash(index,seed)*count);for(let k=0;k<group;k++){const soldier=(first+k*2)%count;events.push({time:time+k*.035,soldier,power:.75+hash(index+10+k,seed)*.5})}time+=(.55+hash(index+20,seed)*.9)/Math.max(.1,rate);index++}return events}
export function sampleShot(events,age,soldier,duration=.13){let power=0;for(const e of events){const t=age-e.time;if(e.soldier===soldier&&t>=0&&t<duration)power=Math.max(power,e.power*(1-t/duration))}return power}
